const RemarkModal = styled(Modal)``;

const RemarkModalContent = styled(ModalContent)`
  max-width: 500px;
`;

const CorporateBatchApproval = () => {
  const [batches, setBatches] = useState([]);
  const [filteredBatches, setFilteredBatches] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [selectedBatch, setSelectedBatch] = useState(null);
  const [showDetails, setShowDetails] = useState(false);
  const [showRemarkModal, setShowRemarkModal] = useState(false);
  const [showSampleDetails, setShowSampleDetails] = useState(false);
  const [sampleData, setSampleData] = useState(null);
  const [sampleLoading, setSampleLoading] = useState(false);
  const [statusChanges, setStatusChanges] = useState({});
  const [remarks, setRemarks] = useState({});
  const [savedTests, setSavedTests] = useState({});
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [processingBatch, setProcessingBatch] = useState(null);
  const [rejectionRemark, setRejectionRemark] = useState("");
  const [currentAction, setCurrentAction] = useState(null);
  const [selectAllReceived, setSelectAllReceived] = useState(false);
const [bulkUpdateInProgress, setBulkUpdateInProgress] = useState(false);

  const navigate = useNavigate();
  const storedName = localStorage.getItem("name");

  const Labbaseurl = process.env.REACT_APP_BACKEND_LAB_BASE_URL;

  // Get current date in YYYY-MM-DD format
  const getCurrentDate = () => {
    const today = new Date();
    const year = today.getFullYear();
    const month = String(today.getMonth() + 1).padStart(2, "0");
    const day = String(today.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  };

  // Initialize dates on component mount
  useEffect(() => {
    const currentDate = getCurrentDate();
    setFromDate(currentDate);
    setToDate(currentDate);
  }, []);

  const fetchBatches = async () => {
    setLoading(true);
    setError("");

    try {
      const params = new URLSearchParams();
      if (fromDate) params.append("from_date", fromDate);
      if (toDate) params.append("to_date", toDate);

      const url = `${Labbaseurl}corporate-batches/?${params.toString()}`;
      const result = await apiRequest(url, "GET");

      if (result.success) {
        setBatches(result.data.data || []);
        setFilteredBatches(result.data.data || []);
      } else {
        console.error("API Error:", result.error);
        setError(result.error || "Failed to fetch batches. Please try again.");
        toast.error(result.error || "Failed to fetch batches");
      }
    } catch (error) {
      console.error("Unexpected error:", error);
      setError("An unexpected error occurred. Please try again.");
      toast.error("An unexpected error occurred");
    } finally {
      setLoading(false);
    }
  };

  // Fetch sample details for a specific batch
  const fetchSampleDetails = async (batchNumber) => {
  setSampleLoading(true);
  setError(""); // Clear previous errors
  
  try {
    console.log('Fetching sample details for batch:', batchNumber);
    
    const result = await apiRequest(
      `${Labbaseurl}get_corporate_Transferred/${batchNumber}/`,
      "GET"
    );

    console.log('Sample details API result:', result);

    if (result.success) {
      // Handle both array and object responses
      let samples = [];
      if (result.data) {
        if (Array.isArray(result.data)) {
          samples = result.data;
        } else if (result.data.data && Array.isArray(result.data.data)) {
          samples = result.data.data;
        } else if (typeof result.data === 'object') {
          samples = [result.data];
        }
      }
      
      console.log('Processed samples:', samples);
      setSampleData(samples);
      
      if (samples.length === 0) {
        setError("No samples found for this batch");
      }
    } else {
      setError(result.error || "Failed to fetch sample details");
      setSampleData([]);
    }
  } catch (error) {
    console.error("Error fetching sample details:", error);
    setError("Failed to fetch sample details. Please try again.");
    setSampleData([]);
  } finally {
    setSampleLoading(false);
  }
};

  const handleStatusChange = (sampleIndex, testIndex, newStatus) => {
    const key = `${sampleIndex}-${testIndex}`;
    setStatusChanges((prev) => ({
      ...prev,
      [key]: newStatus,
    }));

    if (newStatus !== "Rejected") {
      setRemarks((prev) => {
        const updatedRemarks = { ...prev };
        if (updatedRemarks[key]) {
          delete updatedRemarks[key];
        }
        return updatedRemarks;
      });
    }
  };

  const handleRemarksChange = (sampleIndex, testIndex, value) => {
    const key = `${sampleIndex}-${testIndex}`;
    setRemarks((prev) => ({
      ...prev,
      [key]: value,
    }));
  };

  const updateTestStatus = async (sampleIndex, testIndex) => {
    if (!sampleData || !sampleData[sampleIndex]) return;

    const key = `${sampleIndex}-${testIndex}`;
    const updatedStatus = statusChanges[key];
    const sample = sampleData[sampleIndex];
    const testDetails = sample.testdetails[testIndex];
    const updatedRemarks = remarks[key];

    if (!updatedStatus) {
      setError("Please select a status for the test before updating.");
      setTimeout(() => setError(""), 3000);
      return;
    }

    try {
      const response = await apiRequest(
        `${Labbaseurl}update_corporate_sample/${sample.barcode}/`,
        "PUT",
        {
          updates: [
            {
              test_id: testDetails.test_id,
              testname: testDetails.testname,
              samplestatus: updatedStatus,
              remarks: updatedRemarks || null,
              received_by: updatedStatus === "Received" ? storedName : null,
              rejected_by: updatedStatus === "Rejected" ? storedName : null,
              outsourced_by: updatedStatus === "Outsource" ? storedName : null,
              batch_number: sample.batch_number,
            },
          ],
        }
      );

      if (response.success && response.status === 200) {
        setSuccess("Sample status updated successfully!");
        setTimeout(() => setSuccess(""), 3000);

        setSavedTests((prev) => ({
          ...prev,
          [key]: true,
        }));

        // Update the local sampleData
        setSampleData((prevData) => 
          prevData.map((sampleItem, sIdx) =>
            sIdx === sampleIndex
              ? {
                  ...sampleItem,
                  testdetails: sampleItem.testdetails.map((detail, tIdx) =>
                    tIdx === testIndex
                      ? {
                          ...detail,
                          samplestatus: updatedStatus,
                          remarks: updatedRemarks || null,
                        }
                      : detail
                  ),
                }
              : sampleItem
          )
        );
      } else {
        setError(response.error || "Failed to update sample status");
        setTimeout(() => setError(""), 3000);
      }
    } catch (err) {
      setError("Failed to update sample status");
      setTimeout(() => setError(""), 3000);
    }
  };

  useEffect(() => {
    const filtered = batches.filter((batch) => {
      const searchFields = [
        batch.batch_number,
        batch.franchise_id,
        batch.shipment_from,
        batch.shipment_to,
        batch.created_by,
        ...(batch.batch_details || []).map((detail) => detail.barcode),
      ];

      return searchFields.some((field) =>
        field?.toString().toLowerCase().includes(searchTerm.toLowerCase())
      );
    });
    setFilteredBatches(filtered);
  }, [searchTerm, batches]);

 const handleReceive = async (batchNumber) => {
  setCurrentAction({ type: "receive", batch: batchNumber });
  setProcessingBatch(batchNumber);
  setError("");
  setSuccess("");

  try {
    const result = await apiRequest(
      `${Labbaseurl}corporate-receive/${batchNumber}/`,
      "PATCH",
      {
        received: true,
      }
    );

    if (!result.success) {
      throw new Error(result.error || `HTTP error! status: ${result.status}`);
    }

    setBatches((prev) =>
      prev.map((batch) =>
        batch.batch_number === batchNumber
          ? {
              ...batch,
              received: true,
              lastmodified_date: new Date().toISOString(),
              lastmodified_by: "current_user",
            }
          : batch
      )
    );

    setSuccess("Batch received successfully!");
    toast.success("Batch received successfully!");

    // Close the batch details modal
    setShowDetails(false);
    
    // Auto-open sample details modal
    const batch = batches.find(b => b.batch_number === batchNumber);
    if (batch) {
      setSelectedBatch(batch);
      setShowSampleDetails(true);
      await fetchSampleDetails(batchNumber);
    }

  } catch (error) {
    console.error("Error receiving batch:", error);
    let errorMessage = "An unexpected error occurred";
    if (error.message.includes("not found")) {
      errorMessage = "Batch not found";
    } else if (error.message.includes("already marked")) {
      errorMessage = "Batch was already received";
    } else {
      errorMessage = error.message;
    }
    setError(`Failed to receive batch: ${errorMessage}`);
    toast.error(`Failed to receive batch: ${errorMessage}`);
    setTimeout(() => setError(""), 5000);
  } finally {
    setProcessingBatch(null);
    setCurrentAction(null);
  }
};

// 3. New function for bulk status update
const handleSelectAllReceived = () => {
  const newSelectAll = !selectAllReceived;
  setSelectAllReceived(newSelectAll);
  
  if (sampleData && sampleData.length > 0) {
    const newStatusChanges = {};
    
    sampleData.forEach((sample, sampleIndex) => {
      sample.testdetails.forEach((detail, testIndex) => {
        const key = `${sampleIndex}-${testIndex}`;
        if (newSelectAll) {
          newStatusChanges[key] = "Received";
        } else {
          // Remove from statusChanges if it was set to Received
          if (statusChanges[key] === "Received") {
            delete newStatusChanges[key];
          }
        }
      });
    });
    
    if (newSelectAll) {
      setStatusChanges(prev => ({ ...prev, ...newStatusChanges }));
    } else {
      setStatusChanges(prev => {
        const filtered = { ...prev };
        Object.keys(newStatusChanges).forEach(key => {
          if (filtered[key] === "Received") {
            delete filtered[key];
          }
        });
        return filtered;
      });
    }
  }
};

// 4. New bulk update function
const bulkUpdateAllTests = async () => {
  setBulkUpdateInProgress(true);
  setError("");
  setSuccess("");
  
  try {
    const bulkUpdates = [];
    
    sampleData.forEach((sample, sampleIndex) => {
      const sampleUpdates = [];
      
      sample.testdetails.forEach((detail, testIndex) => {
        const key = `${sampleIndex}-${testIndex}`;
        const updatedStatus = statusChanges[key];
        
        if (updatedStatus) {
          sampleUpdates.push({
            test_id: detail.test_id,
            testname: detail.testname,
            samplestatus: updatedStatus,
            remarks: remarks[key] || null,
            received_by: updatedStatus === "Received" ? storedName : null,
            rejected_by: updatedStatus === "Rejected" ? storedName : null,
            outsourced_by: updatedStatus === "Outsource" ? storedName : null,
            batch_number: sample.batch_number,
          });
        }
      });
      
      if (sampleUpdates.length > 0) {
        bulkUpdates.push({
          barcode: sample.barcode,
          updates: sampleUpdates
        });
      }
    });
    
    if (bulkUpdates.length === 0) {
      setError("No changes to update. Please select tests to update.");
      setTimeout(() => setError(""), 3000);
      return;
    }

    const result = await apiRequest(
      `${Labbaseurl}update_corporate_sample/${selectedBatch.batch_number}/`,
      "PUT",
      {
        bulk_updates: bulkUpdates
      }
    );
    
    if (result.success) {
      setSuccess(`Successfully updated ${result.success_count || bulkUpdates.length} test statuses!`);
      
      // Mark all updated tests as saved
      const newSavedTests = {};
      Object.keys(statusChanges).forEach(key => {
        newSavedTests[key] = true;
      });
      setSavedTests(prev => ({ ...prev, ...newSavedTests }));
      
      // Update local sample data
      setSampleData(prevData => 
        prevData.map((sampleItem, sIdx) => ({
          ...sampleItem,
          testdetails: sampleItem.testdetails.map((detail, tIdx) => {
            const key = `${sIdx}-${tIdx}`;
            const updatedStatus = statusChanges[key];
            
            if (updatedStatus) {
              return {
                ...detail,
                samplestatus: updatedStatus,
                remarks: remarks[key] || null,
              };
            }
            return detail;
          }),
        }))
      );
      
      setTimeout(() => setSuccess(""), 3000);
    } else {
      setError(result.error || "Failed to update test statuses. Please try again.");
      setTimeout(() => setError(""), 3000);
    }
    
  } catch (error) {
    console.error("Bulk update error:", error);
    setError("Failed to update test statuses. Please try again.");
    setTimeout(() => setError(""), 3000);
  } finally {
    setBulkUpdateInProgress(false);
  }
};

  const handleReject = (batchNumber) => {
    setCurrentAction({ type: "reject", batch: batchNumber });
    setShowRemarkModal(true);
    setRejectionRemark("");
  };

  const confirmReject = async () => {
    if (!rejectionRemark.trim()) {
      setError("Please provide a reason for rejection");
      return;
    }

    const batchNumber = currentAction.batch;
    setProcessingBatch(batchNumber);
    setShowRemarkModal(false);
    setError("");
    setSuccess("");

    try {
      const result = await apiRequest(
        `${Labbaseurl}corporate-receive/${batchNumber}/`,
        "PATCH",
        {
          received: false,
          remarks: rejectionRemark.trim(),
        }
      );

      if (!result.success) {
        throw new Error(result.error || `HTTP error! status: ${result.status}`);
      }

      setBatches((prev) =>
        prev.map((batch) =>
          batch.batch_number === batchNumber
            ? {
                ...batch,
                received: false,
                remarks: rejectionRemark.trim(),
                is_active: false,
              }
            : batch
        )
      );

      setSuccess("Batch rejected successfully!");
      toast.success("Batch rejected successfully!");

      // Close the detail modal after successful action
      setShowDetails(false);
      setSelectedBatch(null);
    } catch (error) {
      console.error("Error rejecting batch:", error);
      setError(`Failed to reject batch: ${error.message}`);
      toast.error(`Failed to reject batch: ${error.message}`);
      setTimeout(() => setError(""), 5000);
    } finally {
      setProcessingBatch(null);
      setCurrentAction(null);
      setRejectionRemark("");
    }
  };

  const showBatchDetails = (batch) => {
    setSelectedBatch(batch);
    setShowDetails(true);
  };

  const showBatchSampleDetails = async (batch) => {
    setSelectedBatch(batch);
    setShowSampleDetails(true);
    
    // Fetch sample details for this batch
    if (batch.batch_number) {
      await fetchSampleDetails(batch.batch_number);
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const getBatchInitials = (batchNumber) => {
    return batchNumber?.substring(0, 2).toUpperCase() || "N/A";
  };

  const getStatusInfo = (batch) => {
    if (batch.received === true) {
      return { status: "received", text: "Received" };
    } else if (batch.received === false && batch.remarks) {
      return { status: "rejected", text: "Rejected" };
    } else {
      return { status: "pending", text: "Pending" };
    }
  };

  const getSampleStatusBadge = (status) => {
    switch (status) {
      case "Transferred":
        return (
          <SampleStatusBadge status="Transferred">
            <Clock size={12} /> Transferred
          </SampleStatusBadge>
        );
      case "Received":
        return (
          <SampleStatusBadge status="Received">
            <CheckCircle size={12} /> Received
          </SampleStatusBadge>
        );
      case "Rejected":
        return (
          <SampleStatusBadge status="Rejected">
            <X size={12} /> Rejected
          </SampleStatusBadge>
        );
      case "Outsource":
        return (
          <SampleStatusBadge status="Outsource">
            <Activity size={12} /> Outsourced
          </SampleStatusBadge>
        );
      default:
        return (
          <SampleStatusBadge>
            <Clock size={12} /> {status}
          </SampleStatusBadge>
        );
    }
  };

  const closeModal = () => {
    setShowDetails(false);
    setShowSampleDetails(false);
    setSelectedBatch(null);
    setSampleData(null);
    setStatusChanges({});
    setRemarks({});
    setSavedTests({});
    setError("");
    setSuccess("");
  };

  // Fetch batches when component mounts or when dates are initialized
  useEffect(() => {
    if (fromDate && toDate) {
      fetchBatches();
    }
  }, [fromDate, toDate]);

  return (
    <>
      <GlobalStyle />
      <Container>
        <MainContent>
          <Header>
            <h1>Corporate Healthcare Batch Approval</h1>
            <p>Manage and approve Corporate Healthcare batch shipments with ease</p>
          </Header>

          {error && <ErrorMessage>{error}</ErrorMessage>}
          {success && <SuccessMessage>{success}</SuccessMessage>}

          <FilterCard>
            <FilterGrid>
              <InputGroup>
                <label>Search</label>
                <InputIcon hasLabel>
                  <Search size={20} />
                </InputIcon>
                <StyledInput
                  type="text"
                  placeholder="Search by batch, Company, barcode..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  hasIcon
                />
              </InputGroup>

              <InputGroup>
                <label>From Date</label>
                <InputIcon hasLabel>
                  <Calendar size={20} />
                </InputIcon>
                <StyledInput
                  type="date"
                  value={fromDate}
                  onChange={(e) => setFromDate(e.target.value)}
                  hasIcon
                />
              </InputGroup>

              <InputGroup>
                <label>To Date</label>
                <InputIcon hasLabel>
                  <Calendar size={20} />
                </InputIcon>
                <StyledInput
                  type="date"
                  value={toDate}
                  onChange={(e) => setToDate(e.target.value)}
                  hasIcon
                />
              </InputGroup>
            </FilterGrid>
          </FilterCard>

          <ResultsInfo>
            Showing {filteredBatches.length} of {batches.length} batches
          </ResultsInfo>

          <TableContainer>
            <Table>
              <TableHeader>
                <tr>
                  <th>Batch Information</th>
                  <th>Company</th>
                  <th>Shipment Details</th>
                  <th>Specimen Count</th>
                  <th>Created</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </TableHeader>
              <TableBody>
                {loading ? (
                  <tr>
                    <td colSpan="7">
                      <LoadingContainer>
                        <div className="spinner"></div>
                        <div className="text">Loading batches...</div>
                      </LoadingContainer>
                    </td>
                  </tr>
                ) : filteredBatches.length === 0 ? (
                  <tr>
                    <td colSpan="7">
                      <EmptyState>
                        <FileText className="icon" size={64} />
                        <div className="title">No batches found</div>
                        <div className="description">
                          Try adjusting your search criteria or check if there
                          are any pending batches
                        </div>
                      </EmptyState>
                    </td>
                  </tr>
                ) : (
                  filteredBatches.map((batch) => {
                    const statusInfo = getStatusInfo(batch);
                    return (
                      <tr key={batch._id}>
                        <td>
                          <BatchInfo>
                            <div className="icon">
                              {getBatchInitials(batch.batch_number)}
                            </div>
                            <div className="details">
                              <div className="batch-number">
                                Batch #{batch.batch_number}
                              </div>
                              <div className="franchise-id">
                                Company: {batch.company_id}
                              </div>
                              <div className="barcode-count">
                                <FileText size={12} />
                                {batch.batch_details?.length || 0} barcodes
                              </div>
                            </div>
                          </BatchInfo>
                        </td>
                        <td>
                          <div style={{ fontWeight: "600", color: "#1f2937" }}>
                            {batch.franchise_id}
                          </div>
                        </td>
                        <td>
                          <ShipmentInfo>
                            <div className="icon">
                              <Package size={20} />
                            </div>
                            <div className="details">
                              <div className="route">
                                <MapPin size={14} />
                                Route
                              </div>
                              <div className="from-to">
                                {batch.shipment_from} → {batch.shipment_to}
                              </div>
                            </div>
                          </ShipmentInfo>
                        </td>
                        <td>
                          <div>
                            {batch.specimen_count?.map((specimen, index) => (
                              <div
                                key={index}
                                style={{ marginBottom: "0.25rem" }}
                              >
                                <span
                                  style={{
                                    fontWeight: "600",
                                    fontSize: "0.9rem",
                                  }}
                                >
                                  {specimen.specimen_type}
                                </span>
                                <span
                                  style={{
                                    color: "#6b7280",
                                    fontSize: "0.8rem",
                                    marginLeft: "0.5rem",
                                  }}
                                >
                                  ({specimen.count})
                                </span>
                              </div>
                            ))}
                          </div>
                        </td>
                        <td>
                          <div
                            style={{
                              fontWeight: "600",
                              marginBottom: "0.25rem",
                            }}
                          >
                            {formatDate(batch.created_date)}
                          </div>
                          <div style={{ color: "#6b7280", fontSize: "0.9rem" }}>
                            by {batch.created_by}
                          </div>
                        </td>
                        <td>
                          <StatusBadge status={statusInfo.status}>
                            {statusInfo.status === "received" && (
                              <CheckCircle size={16} />
                            )}
                            {statusInfo.status === "rejected" && (
                              <XCircle size={16} />
                            )}
                            {statusInfo.status === "pending" && (
                              <Clock size={16} />
                            )}
                            {statusInfo.text}
                          </StatusBadge>
                          {batch.remarks && (
                            <div
                              style={{
                                fontSize: "0.7rem",
                                color: "#dc2626",
                                marginTop: "0.25rem",
                                fontStyle: "italic",
                              }}
                            >
                              {batch.remarks}
                            </div>
                          )}
                        </td>
                        <td>
                          <ActionButtonGroup>
                            <ActionButton
                              variant="view"
                              onClick={() => showBatchDetails(batch)}
                            >
                              <Eye size={16} />
                              View Details
                            </ActionButton>
                            
                          </ActionButtonGroup>
                        </td>
                      </tr>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </TableContainer>

          {/* Batch Details Modal */}
          {showDetails && selectedBatch && (
            <Modal>
              <ModalContent>
                <ModalHeader>
                  <h2>Batch Details - #{selectedBatch.batch_number}</h2>
                  <button onClick={closeModal}>
                    <X size={24} />
                  </button>
                </ModalHeader>
                <ModalBody>
                  {error && (
                    <ErrorMessage>
                      <AlertCircle size={16} />
                      {error}
                    </ErrorMessage>
                  )}

                  {success && (
                    <SuccessMessage>
                      <CheckCircle size={16} />
                      {success}
                    </SuccessMessage>
                  )}

                  <DetailSection>
                    <h3>
                      <Package size={20} />
                      Batch Information
                    </h3>
                    <DetailGrid>
                      <DetailItem>
                        <div className="label">Batch Number</div>
                        <div className="value">
                          {selectedBatch.batch_number}
                        </div>
                      </DetailItem>
                      <DetailItem>
                        <div className="label">Company ID</div>
                        <div className="value">
                          {selectedBatch.company_id}
                        </div>
                      </DetailItem>
                      <DetailItem>
                        <div className="label">Created By</div>
                        <div className="value">{selectedBatch.created_by}</div>
                      </DetailItem>
                      <DetailItem>
                        <div className="label">Created Date</div>
                        <div className="value">
                          {formatDate(selectedBatch.created_date)}
                        </div>
                      </DetailItem>
                      <DetailItem>
                        <div className="label">Last Modified</div>
                        <div className="value">
                          {formatDate(selectedBatch.lastmodified_date)}
                        </div>
                      </DetailItem>
                      <DetailItem>
                        <div className="label">Status</div>
                        <div className="value">
                          <StatusBadge
                            status={getStatusInfo(selectedBatch).status}
                          >
                            {getStatusInfo(selectedBatch).text}
                          </StatusBadge>
                        </div>
                      </DetailItem>
                    </DetailGrid>
                    {selectedBatch.remarks && (
                      <DetailItem style={{ marginTop: "1rem" }}>
                        <div className="label">Remarks</div>
                        <div className="value" style={{ color: "#dc2626" }}>
                          {selectedBatch.remarks}
                        </div>
                      </DetailItem>
                    )}
                  </DetailSection>

                                   <DetailSection>
                    <h3>
                      <TestTube size={20} />
                      Specimen Count
                    </h3>
                    {(selectedBatch.specimen_count || []).map(
                      (specimen, index) => (
                        <SpecimenCard key={index}>
                          <div className="specimen-type">
                            {specimen.specimen_type}
                          </div>
                          <div className="specimen-count">
                            Count: {specimen.count}
                          </div>
                        </SpecimenCard>
                      )
                    )}
                  </DetailSection>

                  <DetailSection>
                    <h3>
                      <FileText size={20} />
                      Batch Details (Barcodes)
                    </h3>
                    <DetailGrid>
                      {(selectedBatch.batch_details || []).map(
                        (detail, index) => (
                          <DetailItem key={index}>
                            <div className="label">Barcode #{index + 1}</div>
                            <div className="value">{detail.barcode}</div>
                          </DetailItem>
                        )
                      )}
                    </DetailGrid>
                  </DetailSection>
                </ModalBody>
                
                {/* Modal Actions - Only show if status is pending */}
                {getStatusInfo(selectedBatch).status === "pending" && (
                  <ModalActions>
                    <ActionButton
                      variant="reject"
                      onClick={() => handleReject(selectedBatch.batch_number)}
                      disabled={processingBatch === selectedBatch.batch_number}
                    >
                      <XCircle size={16} />
                      {processingBatch === selectedBatch.batch_number &&
                      currentAction?.type === "reject"
                        ? "Rejecting..."
                        : "Reject Batch"}
                    </ActionButton>
                    <ActionButton
                      variant="approve"
                      onClick={() => handleReceive(selectedBatch.batch_number)}
                      disabled={processingBatch === selectedBatch.batch_number}
                    >
                      <CheckCircle size={16} />
                      {processingBatch === selectedBatch.batch_number &&
                      currentAction?.type === "receive"
                        ? "Receiving..."
                        : "Receive Batch"}
                    </ActionButton>
                  </ModalActions>
                )}
              </ModalContent>
            </Modal>
          )}

          {/* Sample Details Modal */}
         {showSampleDetails && selectedBatch && (
  <Modal>
    <ModalContent>
      <ModalHeader>
        <h2>Sample Details - Batch #{selectedBatch.batch_number}</h2>
        <button onClick={closeModal}>
          <X size={24} />
        </button>
      </ModalHeader>
      <ModalBody>
        {error && (
          <ErrorMessage>
            <AlertCircle size={16} />
            {error}
          </ErrorMessage>
        )}

        {success && (
          <SuccessMessage>
            <CheckCircle size={16} />
            {success}
          </SuccessMessage>
        )}

        {sampleLoading ? (
          <LoadingContainer>
            <div className="spinner"></div>
            <div className="text">Loading sample details...</div>
          </LoadingContainer>
        ) : sampleData && sampleData.length > 0 ? (
          <>
            <div style={{ 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center',
              marginBottom: '1rem',
              padding: '1rem',
              backgroundColor: '#f3f4f6',
              borderRadius: '8px'
            }}>
              <div style={{ color: "#6b7280", fontSize: "1rem" }}>
                Found {sampleData.length} samples in this batch
              </div>
              
              <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                <label style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  gap: '0.5rem',
                  fontSize: '0.9rem',
                  fontWeight: '600',
                  color: '#374151'
                }}>
                  <input
                    type="checkbox"
                    checked={selectAllReceived}
                    onChange={handleSelectAllReceived}
                    disabled={bulkUpdateInProgress}
                    style={{
                      width: '16px',
                      height: '16px',
                      cursor: 'pointer'
                    }}
                  />
                  Mark All as Received
                </label>
                
                <ActionButton
                  variant="success"
                  onClick={bulkUpdateAllTests}
                  disabled={bulkUpdateInProgress || Object.keys(statusChanges).length === 0}
                >
                  <Activity size={16} />
                  {bulkUpdateInProgress ? "Updating..." : "Update All Selected"}
                </ActionButton>
              </div>
            </div>
            
            {sampleData.map((sample, sampleIndex) => (
              <div key={`sample-${sampleIndex}-${sample.barcode || sampleIndex}`} style={{ marginBottom: "3rem" }}>
                <PatientInfoCard>
                  <PatientInfoItem>
                    <User size={16} />
                    <PatientInfoLabel>Employee:</PatientInfoLabel>
                    <PatientInfoValue>
                      {sample.employee_name || 'N/A'}
                    </PatientInfoValue>
                  </PatientInfoItem>
                  <PatientInfoItem>
                    <Tag size={16} />
                    <PatientInfoLabel>ID:</PatientInfoLabel>
                    <PatientInfoValue>
                      {sample.employee_id || 'N/A'}
                    </PatientInfoValue>
                  </PatientInfoItem>
                  <PatientInfoItem>
                    <Calendar size={16} />
                    <PatientInfoLabel>Date:</PatientInfoLabel>
                    <PatientInfoValue>
                      {sample.date ? new Date(sample.date).toLocaleDateString("en-GB") : 'N/A'}
                    </PatientInfoValue>
                  </PatientInfoItem>
                  <PatientInfoItem>
                    <Tag size={16} />
                    <PatientInfoLabel>Barcode:</PatientInfoLabel>
                    <PatientInfoValue>{sample.barcode || 'N/A'}</PatientInfoValue>
                  </PatientInfoItem>
                  <PatientInfoItem>
                    <User size={16} />
                    <PatientInfoLabel>Age:</PatientInfoLabel>
                    <PatientInfoValue>{sample.age || 'N/A'}</PatientInfoValue>
                  </PatientInfoItem>
                  <PatientInfoItem>
                    <Tag size={16} />
                    <PatientInfoLabel>From:</PatientInfoLabel>
                    <PatientInfoValue>
                      {sample.company_id || 'N/A'}
                    </PatientInfoValue>
                  </PatientInfoItem>
                </PatientInfoCard>

                {sample.testdetails && sample.testdetails.length > 0 ? (
                  <TableContainer>
                    <Table>
                      <TableHeader>
                        <tr>
                          <th>Test Name</th>
                          <th>Container Type</th>
                          <th>Department</th>
                          <th>Current Status</th>
                          <th>Update Status</th>
                          <th>Sample Collector</th>
                          <th>Reason for Rejection</th>
                        </tr>
                      </TableHeader>
                      <TableBody>
                        {sample.testdetails.map((detail, testIndex) => {
                          const key = `${sampleIndex}-${testIndex}`;
                          const isStatusRejected = statusChanges[key] === "Rejected";
                          const isTestSaved = savedTests[key];
                          
                          return (
                            <tr key={`test-${sampleIndex}-${testIndex}-${detail.test_id || testIndex}`}>
                              <td style={{ fontWeight: '600' }}>
                                {detail.testname || 'N/A'}
                              </td>
                              <td>{detail.container || 'N/A'}</td>
                              <td>{detail.department || 'N/A'}</td>
                              <td>
                                {getSampleStatusBadge(detail.samplestatus || 'Unknown')}
                              </td>
                              <td>
                                <Select
                                  value={statusChanges[key] || ""}
                                  onChange={(e) =>
                                    handleStatusChange(
                                      sampleIndex,
                                      testIndex,
                                      e.target.value
                                    )
                                  }
                                  disabled={isTestSaved || bulkUpdateInProgress}
                                  style={{
                                    backgroundColor: isTestSaved ? '#f3f4f6' : 'white',
                                    cursor: isTestSaved ? 'not-allowed' : 'pointer'
                                  }}
                                >
                                  <option value="">Select New Status</option>
                                  <option value="Received">Received</option>
                                  <option value="Rejected">Rejected</option>
                                  <option value="Outsource">Outsource</option>
                                </Select>
                              </td>
                              <td>{detail.samplecollector || 'N/A'}</td>
                              <td>
                                {isStatusRejected && !isTestSaved && (
                                  <TextArea
                                    value={remarks[key] || ""}
                                    onChange={(e) =>
                                      handleRemarksChange(
                                        sampleIndex,
                                        testIndex,
                                        e.target.value
                                      )
                                    }
                                    placeholder="Enter rejection reason..."
                                    style={{ minHeight: '60px' }}
                                  />
                                )}
                                {detail.remarks && (
                                  <div
                                    style={{
                                      fontSize: "0.8rem",
                                      color: "#dc2626",
                                      marginTop: "0.25rem",
                                      fontStyle: "italic",
                                      padding: "0.5rem",
                                      backgroundColor: "#fef2f2",
                                      borderRadius: "4px",
                                      border: "1px solid #fecaca"
                                    }}
                                  >
                                    <strong>Previous remarks:</strong> {detail.remarks}
                                  </div>
                                )}
                              </td>
                            </tr>
                          );
                        })}
                      </TableBody>
                    </Table>
                  </TableContainer>
                ) : (
                  <div style={{ 
                    padding: '2rem', 
                    textAlign: 'center', 
                    color: '#6b7280',
                    backgroundColor: '#f9fafb',
                    borderRadius: '12px',
                    border: '1px solid #e5e7eb'
                  }}>
                    <TestTube size={32} style={{ opacity: 0.5, marginBottom: '0.5rem' }} />
                    <div>No test details found for this sample</div>
                  </div>
                )}
              </div>
            ))}
          </>
        ) : (
          <EmptyState>
            <AlertCircle size={48} color="#6b7280" />
            <div className="title">No sample data found</div>
            <div className="description">
              {sampleData === null 
                ? "Click 'View Samples' to load sample details for this batch."
                : "No samples are available for this batch."}
            </div>
          </EmptyState>
        )}
      </ModalBody>
    </ModalContent>
  </Modal>
)}

          {/* Rejection Remarks Modal */}
          {showRemarkModal && currentAction?.type === "reject" && (
            <RemarkModal>
              <RemarkModalContent>
                <ModalHeader>
                  <h2>Reject Batch</h2>
                  <button
                    onClick={() => {
                      setShowRemarkModal(false);
                      setCurrentAction(null);
                      setRejectionRemark("");
                    }}
                  >
                    <X size={24} />
                  </button>
                </ModalHeader>
                <ModalBody>
                  <p style={{ marginBottom: "1rem", color: "#6b7280" }}>
                    Please provide a reason for rejecting batch #
                    {currentAction.batch}:
                  </p>
                  <InputGroup>
                    <label>Rejection Remarks</label>
                    <TextArea
                      placeholder="Enter the reason for rejection..."
                      value={rejectionRemark}
                      onChange={(e) => setRejectionRemark(e.target.value)}
                    />
                  </InputGroup>
                  <div
                    style={{
                      display: "flex",
                      gap: "1rem",
                      justifyContent: "flex-end",
                      marginTop: "2rem",
                    }}
                  >
                    <ActionButton
                      variant="default"
                      onClick={() => {
                        setShowRemarkModal(false);
                        setCurrentAction(null);
                        setRejectionRemark("");
                      }}
                    >
                      Cancel
                    </ActionButton>
                    <ActionButton
                      variant="reject"
                      onClick={confirmReject}
                      disabled={!rejectionRemark.trim()}
                    >
                      <XCircle size={16} />
                      Confirm Rejection
                    </ActionButton>
                  </div>
                </ModalBody>
              </RemarkModalContent>
            </RemarkModal>
          )}
        </MainContent>
      </Container>
    </>
  );
};

export default CorporateBatchApproval;
